  async fetchM2Data() {
    try {
      const resp = await fetch('api.php?action=get_app_init_data');
      if (resp && resp.ok) {
        const text = await resp.text();
        let res = null;
        try { res = JSON.parse(text); } catch (jsonErr) { res = null; }
        if (res && res.success) {
        if (res.organization) this.m2Data.organization = res.organization;
        if (res.founders && res.founders.length) this.m2Data.founders = res.founders;
        if (res.history && res.history.length) this.m2Data.history = res.history;
        if (res.visionMission && res.visionMission.length) this.m2Data.visionMission = res.visionMission;
        if (res.presidents && res.presidents.length) this.m2Data.presidents = res.presidents;
        if (res.advisoryBoard && res.advisoryBoard.length) this.m2Data.advisoryBoard = res.advisoryBoard;
        if (res.honorCouncil && res.honorCouncil.length) this.m2Data.honorCouncil = res.honorCouncil;
        if (res.structure && res.structure.length) this.m2Data.structure = res.structure;
        if (res.periods && res.periods.length) this.m2Data.periods = res.periods;
        if (res.clubs && res.clubs.length) {
          this.m2Data.clubs = res.clubs;
          this.clubs = res.clubs;
        }
        if (res.members && res.members.length) {
          this.m3Data.members = res.members;
          this.users = res.members;
          
          // Auto-sync Header with live record from Supabase database table
          if (this.currentUser && this.currentUser.role !== 'GUEST') {
            const dbUser = res.members.find(m => 
              (this.currentUser.id && m.id === this.currentUser.id) ||
              (this.currentUser.member_id && m.member_id === this.currentUser.member_id) ||
              (this.currentUser.email && m.email && m.email.toLowerCase() === this.currentUser.email.toLowerCase()) ||
              (this.currentUser.username && m.username && m.username.toLowerCase() === this.currentUser.username.toLowerCase())
            );
            if (dbUser) {
              this.currentUser = Object.assign({}, this.currentUser, dbUser);
              const nameEl = document.getElementById('nav-user-name');
              const ddNameEl = document.getElementById('dropdown-user-name');
              const navAvatar = document.getElementById('nav-user-avatar');
              if (nameEl && dbUser.name) nameEl.innerText = dbUser.name;
              if (ddNameEl && dbUser.name) ddNameEl.innerText = dbUser.name;
              if (navAvatar && dbUser.name) navAvatar.innerText = dbUser.name.substring(0, 2).toUpperCase();
            }
          }
        }
        if (res.pendingCount !== undefined) {
          this.m3Data.pendingCount = res.pendingCount;
        }
        if (res.auditLogs && res.auditLogs.length) {
          this.auditLogs = res.auditLogs;
        }

        if (res.clubApplications && res.clubApplications.length) this.m4Data.applications = res.clubApplications;
        if (res.clubApplicationNotes && res.clubApplicationNotes.length) this.m4Data.notes = res.clubApplicationNotes;
        if (res.clubEvaluations && res.clubEvaluations.length) this.m4Data.evaluations = res.clubEvaluations;

        // Simpan data lapak & produk ke AppEngine agar tombol Review bisa menemukannya
        if (res.lapak && res.lapak.length) {
          this.lapak = res.lapak;
          if (window.M7Engine) window.M7Engine.data.lapak = res.lapak;
        }
        if (res.lapakProducts && res.lapakProducts.length) {
          this.lapakProducts = res.lapakProducts;
          if (window.M7Engine) window.M7Engine.data.products = res.lapakProducts;
        }
        if (res.adCampaigns && res.adCampaigns.length) {
          this.adCampaigns = res.adCampaigns;
          if (window.M8Engine) {
            window.M8Engine.data.campaigns = res.adCampaigns;
          }
        }
      }
    }
  } catch (e) {
      console.warn("API Offline / slow, ensuring local fallback data is populated:", e);
    } finally {
      this.hideLoader();
      try {
        this.ensureDataPopulated();
        this.syncCurrentUserStatusFromList();
        this.renderClubsList();
        this.renderLandingPageVisionMission();
        this.renderLandingSponsors();
        this.updateLandingCounters();
        if (this.activeAdminTab === 'm2_org') this.renderM2Module();
        if (this.activeAdminTab === 'm3_membership') this.renderM3Module();
        if (this.activeAdminTab === 'm4_registration') this.renderM4Module();
        if (this.activeAdminTab === 'm1_portal' || this.activeAdminTab === 'dashboard') this.renderAdminDashboard();
      } catch (err) {
        console.warn('Post-fetch rendering warning:', err);
      }
    }
  },

  /**
   * SINKRONISASI STATUS & DATA DARI MASTER USER LIST
   * Setiap kali data member di-load (dari API atau fallback), pastikan
   * currentUser yang sedang login mendapat status terbaru dari master list.
   */
  syncCurrentUserStatusFromList() {
    if (!this.currentUser || this.currentUser.role === 'GUEST') return;
    const u = this.currentUser;
    const masterList = [...(this.users || []), ...((this.m3Data && this.m3Data.members) ? this.m3Data.members : [])];
    const liveData = masterList.find(x =>
      (u.id && x.id === u.id) ||
      (u.username && x.username === u.username) ||
      (u.email && x.email === u.email) ||
      (u.member_id && (x.member_id === u.member_id || x.memberId === u.member_id))
    );
    if (liveData) {
      this.currentUser.status = liveData.status || u.status;
    }

    const realTotal = this.getMemberTotalContribution(this.currentUser);
    const realTierCalc = this.calculateMemberTier(realTotal);
    this.currentUser.totalDonation = realTotal;
    this.currentUser.tier = realTierCalc.tier;

    localStorage.setItem('mbina_session_user', JSON.stringify(this.currentUser));

    const memberView = document.getElementById('view-member-dashboard');
    if (memberView && memberView.style.display !== 'none') {
      this.populateMemberPortalData();
    }
  },

