  downloadMemberTemplate() {
    const csvContent = "\uFEFFNo,Nama Anggota,Jabatan,Status\n" +
      "1,Budi Santoso,Ketua,Aktif\n" +
      "2,Andi Wijaya,Wakil,Aktif\n" +
      "3,Siti Rahayu,Sekretaris,Aktif\n" +
      "4,Rizky Febrian,Bendahara,Aktif\n" +
      "5,Eko Prasetyo,Anggota,Aktif\n";

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "Template_Daftar_Anggota_MBINA.csv";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  },

