  async handleM4DocumentSelect(event, type) {
    const file = event.target.files[0];
    const badge = document.getElementById(`m4-file-${type}-badge`);

    if (!file) {
      if (badge) badge.innerHTML = '';
      return;
    }

    const maxSizeMb = type === 'ad-art' ? 5 : 2;
    if (file.size > maxSizeMb * 1024 * 1024) {
      alert(`⚠️ Ukuran file "${file.name}" melebihi batas maksimum ${maxSizeMb} MB!`);
      event.target.value = '';
      if (badge) badge.innerHTML = '';
      return;
    }

    if (badge) {
      badge.innerHTML = `<span style="color:var(--accent-gold); font-weight:700;">⏳ Mengunggah berkas ${file.name}...</span>`;
    }

    const formData = new FormData();
    formData.append('file', file);
    formData.append('type', type);

    try {
      const res = await fetch('api.php?action=upload_club_document', {
        method: 'POST',
        body: formData
      });
      const data = await res.json();

      if (data.success) {
        if (!this.m4Data.uploadedDocs) this.m4Data.uploadedDocs = {};
        this.m4Data.uploadedDocs[type] = {
          name: file.name,
          url: data.file_url,
          size: (file.size / (1024 * 1024)).toFixed(2) + ' MB'
        };

        if (badge) {
          badge.innerHTML = `<span style="color:var(--primary-emerald); font-weight:700;">✅ Berkas berhasil tersimpan ke server: <strong>${file.name}</strong> (${(file.size / (1024 * 1024)).toFixed(2)} MB)</span>`;
        }
      } else {
        alert('❌ Gagal Mengunggah Berkas: ' + data.message);
        if (badge) badge.innerHTML = '';
      }
    } catch (err) {
      alert('⚠️ Gagal terhubung ke server upload: ' + err.message);
      if (badge) badge.innerHTML = '';
    }
  },

  async submitM4ClubApplication(event) {
    if (event) event.preventDefault();

    const agree = document.getElementById('m4-form-agree')?.checked;
    if (!agree) {
      alert('⚠️ Silakan centang konfirmasi pernyataan kebenaran data terlebih dahulu!');
      return;
    }

    const name = document.getElementById('m4-form-name')?.value.trim();
    const code = document.getElementById('m4-form-code')?.value.trim().toUpperCase();
    const city = document.getElementById('m4-form-city')?.value.trim();
    const chairman = document.getElementById('m4-form-chairman')?.value.trim();
    const phone = document.getElementById('m4-form-chairman-phone')?.value.trim();

    if (!name || !code || !city || !chairman || !phone) {
      alert('⚠️ Mohon lengkapi Nama Klub, Kode Klub, Kota, Nama Ketua, dan No. WhatsApp Ketua!');
      return;
    }

    const docs = this.m4Data.uploadedDocs || {};

    const payload = {
      editing_id: this.m4Data.editingAppId || null,
      name: name,
      code: code,
      alias: code,
      province_id: 'prov_33',
      province_name: document.getElementById('m4-form-province')?.value.trim() || 'Jawa Tengah',
      city: city,
      address: document.getElementById('m4-form-address')?.value.trim() || city,
      founded_year: parseInt((document.getElementById('m4-form-founded')?.value || '2020').substring(0, 4)) || 2020,
      member_count_estimate: parseInt(document.getElementById('m4-form-total-members')?.value || 15),
      club_type: document.getElementById('m4-form-type')?.value || 'CLUB',
      description: document.getElementById('m4-form-desc')?.value.trim() || `Klub Mercedes-Benz ${name}`,
      contact_person: chairman,
      contact_phone: phone,
      contact_email: document.getElementById('m4-form-email')?.value.trim() || `${code.toLowerCase()}@mbclub.or.id`,
      social_media: { instagram: `@${code.toLowerCase()}_official`, facebook: name },
      logo_url: docs['logo']?.url || 'assets/mb_badge.jpg',
      photos: ['assets/mb_hero.jpg'],
      ad_art_url: docs['ad-art']?.url || 'assets/docs/sample_ad_art.pdf',
      management_structure_url: docs['mgmt']?.url || 'assets/docs/sample_pengurus.pdf',
      domicile_url: docs['domicile']?.url || 'assets/docs/sample_domisili.pdf',
      stamp_url: 'assets/docs/sample_stempel.png',
      activity_photos: ['assets/mb_hero.jpg', 'assets/mb_badge.jpg'],
      members_list_url: 'assets/docs/template_daftar_anggota_mbina.csv',
      total_members: parseInt(document.getElementById('m4-form-total-members')?.value || 15),
      has_kta_imi: document.getElementById('m4-form-kta-imi')?.checked ?? true,
      fee_amount: 350000,
      payment_status: 'PAID',
      payment_proof_url: docs['payment']?.url || 'assets/docs/sample_bukti_transfer.jpg',
      submitted_by: this.currentUser?.id || 'usr_guest'
    };

    try {
      const res = await fetch('api.php?action=submit_club_application', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const data = await res.json();
      if (data.success) {
        // Populate modal details
        const elName = document.getElementById('m4-success-club-name');
        const elCode = document.getElementById('m4-success-club-code');
        const modalTitle = document.querySelector('#modal-m4-submission-success h3');
        const modalSub = document.querySelector('#modal-m4-submission-success span');

        if (elName) elName.textContent = payload.name;
        if (elCode) elCode.textContent = `KODE: ${payload.code} • ${payload.city}, ${payload.province_name}`;

        if (payload.editing_id) {
          if (modalTitle) modalTitle.textContent = '✏️ Perubahan Pengajuan Berhasil Disimpan!';
          if (modalSub) modalSub.textContent = 'Perubahan data & berkas klub telah diperbarui dan diajukan ulang ke Pengurus Pusat';
        } else {
          if (modalTitle) modalTitle.textContent = '🎉 Form Pendaftaran Berhasil Terkirim!';
          if (modalSub) modalSub.textContent = 'Menunggu Verifikasi & Peninjauan Pengurus Pusat MB INA';
        }

        // Show Success Modal
        AuthEngine.openModal('modal-m4-submission-success');

        // Reset registration form & doc badges & editing state
        document.getElementById('m4-registration-form')?.reset();
        this.m4Data.editingAppId = null;
        this.m4Data.uploadedDocs = {};
        ['ad-art', 'mgmt', 'domicile', 'logo', 'payment'].forEach(t => {
          const b = document.getElementById(`m4-file-${t}-badge`);
          if (b) b.innerHTML = '';
        });

        // Reset form title & submit button
        const formTitle = document.querySelector('#m4sub-form h3');
        if (formTitle) formTitle.textContent = '📋 Formulir Pendaftaran Klub / Chapter Baru MB INA';

        const submitBtn = document.getElementById('m4-submit-form-btn');
        if (submitBtn) {
          submitBtn.innerHTML = '🚀 Submit Pengajuan Klub Baru';
          submitBtn.style.background = 'var(--primary-emerald)';
          submitBtn.style.borderColor = 'var(--primary-emerald)';
          submitBtn.style.color = '#fff';
        }

        // Refresh database & state
        await this.fetchM4Data();
      } else {
        alert('❌ Gagal Mengirim Pendaftaran: ' + data.message);
      }
    } catch (e) {
      alert('⚠️ Terjadi kesalahan pengiriman: ' + e.message);
    }
  },

  handleM4FormSubmit(event) {
    return this.submitM4ClubApplication(event);
  },

