  applyDonationToUserLocal(don) {
    if (!don || (don.status !== 'SUCCESS' && don.status !== 'CONFIRMED')) return;
    const targetMid = (don.member_id || don.memberId || '').toUpperCase();
    const targetUid = don.user_id || don.userId || '';
    const targetName = (don.donor_name || don.donorName || '').toLowerCase();
    const donAmt = Number(don.amount || 0);
    if (!donAmt) return;

    if (!don._appliedToUser) {
      don._appliedToUser = true;

      const applyToUser = (u) => {
        if (!u) return;
        const uMid = (u.member_id || u.memberId || '').toUpperCase();
        const uUid = u.id || u.userId || '';
        const uName = (u.name || u.username || '').toLowerCase();

        const match = (targetMid && uMid && targetMid === uMid) ||
                      (targetUid && uUid && targetUid === uUid) ||
                      (targetName && uName && (targetName === uName || uName.includes(targetName) || targetName.includes(uName)));

        if (match) {
          const curTot = Number(u.total_donation || u.totalDonation || 0);
          const newTot = curTot + donAmt;
          u.total_donation = newTot;
          u.totalDonation = newTot;
          const tierCalc = this.calculateMemberTier(newTot);
          u.tier = tierCalc.tier;
        }
      };

      (this.users || []).forEach(u => applyToUser(u));
      if (this.m3Data && Array.isArray(this.m3Data.members)) this.m3Data.members.forEach(u => applyToUser(u));
      if (this.currentUser) applyToUser(this.currentUser);
    }
  },

  verifyDonation(donationId, isApproved) {
    if (!this.donationData || !Array.isArray(this.donationData.donations)) return;
    const don = this.donationData.donations.find(d => d.id === donationId);
    if (!don) return;

    if (isApproved) {
      don.status = 'SUCCESS';
      this.applyDonationToUserLocal(don);
      // Create receipt if not present
      let rcpt = (this.donationData.receipts || []).find(r => r.donation_id === donationId);
      if (!rcpt) {
        rcpt = {
          id: 'rec_' + Date.now(),
          donation_id: donationId,
          receipt_number: 'REC-2026-' + String(Math.floor(1000 + Math.random() * 9000)),
          sent_to_email: true,
          created_at: new Date().toLocaleString('id-ID')
        };
        if (!this.donationData.receipts) this.donationData.receipts = [];
        this.donationData.receipts.unshift(rcpt);
      }
      window.showToast(`Donasi dari ${don.donor_name} sebesar Rp ${parseFloat(don.amount).toLocaleString('id-ID')} telah disetujui dan Digital Receipt #${rcpt.receipt_number} resmi diterbitkan.`, 'success');
    } else {
      don.status = 'REJECTED';
      window.showToast(`Donasi dari ${don.donor_name} telah ditolak.`, 'error');
    }

    this.renderDonationDonorTable();
    this.renderDonationReceiptsTable();
    this.renderDonationCampaignCards();
    if (typeof this.populateMemberPortalData === 'function') this.populateMemberPortalData();
    if (typeof this.renderM3MemberList === 'function') this.renderM3MemberList();
  },

  viewDonationReceipt(receiptIdOrDonationId) {
    let rcpt = (this.donationData?.receipts || []).find(r => r.id === receiptIdOrDonationId || r.donation_id === receiptIdOrDonationId);
    let don = (this.donationData?.donations || []).find(d => d.id === receiptIdOrDonationId || (rcpt && d.id === rcpt.donation_id)) || {};

    if (!rcpt) {
      rcpt = {
        id: 'rec_default',
        donation_id: don.id || 'don_1',
        receipt_number: 'REC-2026-0001',
        sent_to_email: true,
        created_at: don.created_at || '10/08/2026 10:00'
      };
    }

    const modalNum = document.getElementById('receipt-modal-number');
    const modalName = document.getElementById('receipt-modal-donor-name');
    const modalMember = document.getElementById('receipt-modal-donor-member');
    const modalAmount = document.getElementById('receipt-modal-amount');
    const modalDate = document.getElementById('receipt-modal-date');

    if (modalNum) modalNum.innerText = rcpt.receipt_number;
    if (modalName) modalName.innerText = don.donor_name || 'Derist Touriano';
    if (modalMember) modalMember.innerText = don.member_id || 'MBINA-HQ-2026-000001';
    if (modalAmount) modalAmount.innerText = 'Rp ' + parseFloat(don.amount || 5000000).toLocaleString('id-ID');
    if (modalDate) modalDate.innerText = rcpt.created_at || '10/08/2026';

    if (window.AuthEngine) {
      window.AuthEngine.openModal('modal-digital-receipt');
    } else if (typeof AuthEngine !== 'undefined') {
      AuthEngine.openModal('modal-digital-receipt');
    }
  },

