  // ─── EXPORT FUNCTIONS ─────────────────────────────────────────────
  exportFinancialPDF: function(type) {
    const win = window.open('', '_blank');
    const incomes  = this.data.transactions.filter(t => t.type === 'INCOME');
    const expenses = this.data.transactions.filter(t => t.type === 'EXPENSE');
    const totalIn  = incomes.reduce((s, t) => s + parseInt(t.amount || 0), 0);
    const totalOut = expenses.reduce((s, t) => s + parseInt(t.amount || 0), 0);
    const net = totalIn - totalOut;
    const fmt = v => 'Rp ' + new Intl.NumberFormat('id-ID').format(v);
    win.document.write(`<!DOCTYPE html><html><head><title>Laporan Keuangan MB INA</title>
      <style>body{font-family:Arial,sans-serif;padding:40px;color:#111;} h2{color:#d97706;} table{width:100%;border-collapse:collapse;margin:16px 0;} th{background:#f59e0b;padding:10px;text-align:left;} td{padding:8px 10px;border-bottom:1px solid #ddd;} .total-row{font-weight:900;font-size:1.05rem;} @media print{button{display:none;}}</style>
      </head><body>
      <h2>MB INA MOTOR INDONESIA</h2>
      <h3>📊 LAPORAN LABA / RUGI — Jan–Des 2026</h3>
      <p>Tanggal Cetak: ${new Date().toLocaleString('id-ID')}</p>
      <h4>PENDAPATAN</h4>
      <table><thead><tr><th>Kategori</th><th>Deskripsi</th><th style="text-align:right;">Jumlah</th></tr></thead><tbody>
        ${incomes.map(t => `<tr><td>${t.category}</td><td>${t.description}</td><td style="text-align:right;">${fmt(t.amount)}</td></tr>`).join('')}
        <tr class="total-row" style="background:#fef3c7;"><td colspan="2">TOTAL PENDAPATAN</td><td style="text-align:right;color:#d97706;">${fmt(totalIn)}</td></tr>
      </tbody></table>
      <h4>BEBAN</h4>
      <table><thead><tr><th>Kategori</th><th>Deskripsi</th><th style="text-align:right;">Jumlah</th></tr></thead><tbody>
        ${expenses.map(t => `<tr><td>${t.category}</td><td>${t.description}</td><td style="text-align:right;">(${fmt(t.amount)})</td></tr>`).join('')}
        <tr class="total-row" style="background:#fee2e2;"><td colspan="2">TOTAL BEBAN</td><td style="text-align:right;color:#dc2626;">(${fmt(totalOut)})</td></tr>
      </tbody></table>
      <table style="background:${net>=0?'#d1fae5':'#fee2e2'};"><tr class="total-row"><td>LABA BERSIH</td><td style="text-align:right;font-size:1.2rem;color:${net>=0?'#059669':'#dc2626'};">${fmt(net)}</td></tr></table>
      <p style="margin-top:40px;"><button onclick="window.print()" style="background:#d97706;color:#fff;border:none;padding:8px 20px;border-radius:6px;cursor:pointer;">🖨️ Print</button></p>
      </body></html>`);
    win.document.close();
  },

  exportFinancialExcel: function() {
    const incomes  = this.data.transactions.filter(t => t.type === 'INCOME');
    const expenses = this.data.transactions.filter(t => t.type === 'EXPENSE');
    const totalIn  = incomes.reduce((s, t) => s + parseInt(t.amount || 0), 0);
    const totalOut = expenses.reduce((s, t) => s + parseInt(t.amount || 0), 0);
    let csv = '\uFEFFLaporan Keuangan MB INA - 2026\n\n';
    csv += 'PENDAPATAN\nKategori,Deskripsi,Jumlah\n';
    incomes.forEach(t => { csv += `"${t.category}","${t.description}",${t.amount}\n`; });
    csv += `"TOTAL PENDAPATAN",,${totalIn}\n\nBEBAN\nKategori,Deskripsi,Jumlah\n`;
    expenses.forEach(t => { csv += `"${t.category}","${t.description}",${t.amount}\n`; });
    csv += `"TOTAL BEBAN",,${totalOut}\n\n"LABA BERSIH",,${totalIn - totalOut}\n`;
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `LapKeu_MBINA_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  },

  exportEndorseExcel: function() {
    let csv = '\uFEFFNo,No. Kontrak,Mitra,Paket,Nilai (Rp),Mulai,Akhir,Status\n';
    this.data.contracts.forEach((c, i) => {
      csv += `"${i+1}","${c.contract_number}","${c.partner_name}","${c.package_name || c.package_id}",${c.total_amount},"${c.start_date}","${c.end_date}","${c.status}"\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `Endorse_Contracts_MBINA_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  },

