  // ─── MODAL: PACKAGE ──────────────────────────────────────────────
  openPackageModal: function(pkgId) {
    const modal = document.getElementById('modal-endorse-package');
    if (!modal) return;
    document.getElementById('pkg-form-id').value = pkgId || '';
    if (pkgId) {
      const pkg = this.data.packages.find(p => p.id === pkgId);
      if (pkg) {
        document.getElementById('pkg-form-name').value     = pkg.name;
        document.getElementById('pkg-form-price').value    = pkg.price;
        document.getElementById('pkg-form-duration').value = pkg.duration;
        document.getElementById('pkg-form-forum').value    = pkg.forum_posts;
        document.getElementById('pkg-form-social').value   = pkg.social_posts;
        document.getElementById('pkg-form-banner').checked  = pkg.banner === true || pkg.banner === 'true' || pkg.banner === 't';
        document.getElementById('pkg-form-mention').checked = pkg.mention_event === true || pkg.mention_event === 'true' || pkg.mention_event === 't';
      }
    } else {
      document.getElementById('form-endorse-package')?.reset();
    }
    modal.style.display = 'flex';
    document.body.style.overflow = 'hidden';
  },

  closePackageModal: function() {
    const modal = document.getElementById('modal-endorse-package');
    if (modal) modal.style.display = 'none';
    document.body.style.overflow = '';
  },

  submitPackageForm: async function(e) {
    e.preventDefault();
    const pkgId = document.getElementById('pkg-form-id')?.value || '';
    const payload = {
      id: pkgId,
      name:          document.getElementById('pkg-form-name')?.value || '',
      price:         parseInt(document.getElementById('pkg-form-price')?.value || '0'),
      duration:      parseInt(document.getElementById('pkg-form-duration')?.value || '1'),
      forum_posts:   parseInt(document.getElementById('pkg-form-forum')?.value || '0'),
      social_posts:  parseInt(document.getElementById('pkg-form-social')?.value || '0'),
      banner:        document.getElementById('pkg-form-banner')?.checked || false,
      mention_event: document.getElementById('pkg-form-mention')?.checked || false,
      is_active:     true
    };
    const action = pkgId ? 'update_endorse_package' : 'create_endorse_package';
    try {
      const res = await fetch(`api.php?action=${action}`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload)
      }).then(r => r.json());
      if (res && res.success) {
        this.closePackageModal();
        await this.fetchData();
      } else {
        alert(`❌ ${res?.message || 'Gagal menyimpan paket'}`);
      }
    } catch (err) {
      // fallback: update local data
      if (pkgId) {
        const idx = this.data.packages.findIndex(p => p.id === pkgId);
        if (idx >= 0) Object.assign(this.data.packages[idx], payload);
      } else {
        payload.id = 'pkg_' + Date.now();
        this.data.packages.push(payload);
      }
      this.closePackageModal();
      this.renderAll();
    }
  },

  deletePackage: async function(pkgId) {
    if (!confirm('Yakin ingin menghapus paket ini?')) return;
    try {
      await fetch('api.php?action=delete_endorse_package', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ id: pkgId })
      });
    } catch (e) {}
    this.data.packages = this.data.packages.filter(p => p.id !== pkgId);
    this.renderAll();
  },

