  fetchData: async function() {
    try {
      const res = await fetch('api.php?action=get_m9_data').then(r => r.json());
      if (res && res.success) {
        this.data.kpi = res.kpi || this.data.kpi;
        this.data.memberGrowth = res.memberGrowth || [];
        this.data.clubRanking = res.clubRanking || [];
        this.data.tierDist = res.tierDist || [];
        this.data.forumStats = res.forumStats || [];
        this.data.endorseContracts = res.endorseContracts || [];
        this.data.transactions = res.transactions || [];
        this.data.scheduledReports = res.scheduledReports || [];
        this.data.perfTargets = res.perfTargets || [];
      } else {
        console.warn('M9 API returned error, UI will show empty state');
      }
    } catch(e) {
      console.warn('M9 API offline, UI will show empty state', e);
    }
    this.renderAll();
  },

