      { id: 'sch_002', name: 'Laporan Mingguan Keanggotaan', report_type: 'MEMBERSHIP', frequency: 'WEEKLY', recipients: '["sekretaris@mbina.or.id"]', format: 'EXCEL', is_active: true, last_sent_at: '2026-08-07' }
